25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1fs
29	`default_nettype none
30	
31	/*
32	 * PTP clock CDC (clock domain crossing) module
33	 */
34	module ptp_clock_cdc #
35	(
36	    parameter TS_WIDTH = 96,
37	    parameter NS_WIDTH = 4,
38	    parameter LOG_RATE = 3,
39	    parameter PIPELINE_OUTPUT = 0
40	)
41	(
42	    input  wire                 input_clk,
43	    input  wire                 input_rst,
44	    input  wire                 output_clk,
45	    input  wire                 output_rst,
46	    input  wire                 sample_clk,
47	
48	    /*
49	     * Timestamp inputs from source PTP clock
50	     */
51	    input  wire [TS_WIDTH-1:0]  input_ts,
52	    input  wire                 input_ts_step,
53	
54	    /*
55	     * Timestamp outputs
56	     */
57	    output wire [TS_WIDTH-1:0]  output_ts,
58	    output wire                 output_ts_step,
59	
60	    /*
61	     * PPS output
62	     */
63	    output wire                 output_pps,
64	
65	    /*
66	     * Status
67	     */
68	    output wire                 locked
69	);
70	
71	// bus width assertions
72	initial begin
73	    if (TS_WIDTH != 64 && TS_WIDTH != 96) begin
74	        $error("Error: Timestamp width must be 64 or 96");
75	        $finish;
76	    end
77	end
78	
79	localparam FNS_WIDTH = 16;
80	
81	localparam TS_NS_WIDTH = TS_WIDTH == 96 ? 30 : 48;
82	localparam TS_FNS_WIDTH = FNS_WIDTH > 16 ? 16 : FNS_WIDTH;
83	
84	localparam CMP_FNS_WIDTH = 4;
85	
86	localparam PHASE_CNT_WIDTH = LOG_RATE;
87	localparam PHASE_ACC_WIDTH = PHASE_CNT_WIDTH+16;
88	
89	localparam LOG_SAMPLE_SYNC_RATE = LOG_RATE;
90	localparam SAMPLE_ACC_WIDTH = LOG_SAMPLE_SYNC_RATE+2;
91	
92	localparam LOG_PHASE_ERR_RATE = 4;
93	localparam PHASE_ERR_ACC_WIDTH = LOG_PHASE_ERR_RATE+2;
94	
95	localparam DEST_SYNC_LOCK_WIDTH = 7;
96	localparam FREQ_LOCK_WIDTH = 8;
97	localparam PTP_LOCK_WIDTH = 8;
98	
99	localparam TIME_ERR_INT_WIDTH = NS_WIDTH+FNS_WIDTH;
100	
101	localparam [30:0] NS_PER_S = 31'd1_000_000_000;
102	
103	reg [NS_WIDTH+FNS_WIDTH-1:0] period_ns_reg = 0, period_ns_next = 0;
104	reg [NS_WIDTH+FNS_WIDTH-1:0] period_ns_delay_reg = 0, period_ns_delay_next = 0;
105	reg [31+FNS_WIDTH-1:0] period_ns_ovf_reg = 0, period_ns_ovf_next = 0;
106	
107	reg [47:0] src_ts_s_capt_reg = 0;
108	reg [TS_NS_WIDTH+CMP_FNS_WIDTH-1:0] src_ts_ns_capt_reg = 0;
109	reg src_ts_step_capt_reg = 0;
110	
111	reg [47:0] dest_ts_s_capt_reg = 0;
112	reg [TS_NS_WIDTH+CMP_FNS_WIDTH-1:0] dest_ts_ns_capt_reg = 0;
113	
114	reg [47:0] src_ts_s_sync_reg = 0;
115	reg [TS_NS_WIDTH+CMP_FNS_WIDTH-1:0] src_ts_ns_sync_reg = 0;
116	reg src_ts_step_sync_reg = 0;
117	
118	reg [47:0] ts_s_reg = 0, ts_s_next = 0;
119	reg [TS_NS_WIDTH+FNS_WIDTH-1:0] ts_ns_reg = 0, ts_ns_next = 0;
120	reg [TS_NS_WIDTH+FNS_WIDTH-1:0] ts_ns_inc_reg = 0, ts_ns_inc_next = 0;
121	reg [TS_NS_WIDTH+FNS_WIDTH+1-1:0] ts_ns_ovf_reg = {TS_NS_WIDTH+FNS_WIDTH+1{1'b1}}, ts_ns_ovf_next = 0;
122	
123	reg ts_step_reg = 1'b0, ts_step_next;
124	
125	reg pps_reg = 1'b0;
126	
127	reg [47:0] ts_s_pipe_reg[0:PIPELINE_OUTPUT-1];
128	reg [TS_NS_WIDTH+CMP_FNS_WIDTH-1:0] ts_ns_pipe_reg[0:PIPELINE_OUTPUT-1];
129	reg ts_step_pipe_reg[0:PIPELINE_OUTPUT-1];
130	reg pps_pipe_reg[0:PIPELINE_OUTPUT-1];
131	
132	reg [PHASE_CNT_WIDTH-1:0] src_phase_reg = {PHASE_CNT_WIDTH{1'b0}};
133	reg [PHASE_ACC_WIDTH-1:0] dest_phase_reg = {PHASE_ACC_WIDTH{1'b0}}, dest_phase_next;
134	reg [PHASE_ACC_WIDTH-1:0] dest_phase_inc_reg = {PHASE_ACC_WIDTH{1'b0}}, dest_phase_inc_next;
135	
136	reg src_sync_reg = 1'b0;
137	reg src_update_reg = 1'b0;
138	reg src_phase_sync_reg = 1'b0;
139	reg dest_sync_reg = 1'b0;
140	reg dest_update_reg = 1'b0, dest_update_next = 1'b0;
141	reg dest_phase_sync_reg = 1'b0;
142	
143	reg src_sync_sync1_reg = 1'b0;
144	reg src_sync_sync2_reg = 1'b0;
145	reg src_sync_sync3_reg = 1'b0;
146	reg src_phase_sync_sync1_reg = 1'b0;
147	reg src_phase_sync_sync2_reg = 1'b0;
148	reg src_phase_sync_sync3_reg = 1'b0;
149	reg dest_phase_sync_sync1_reg = 1'b0;
150	reg dest_phase_sync_sync2_reg = 1'b0;
151	reg dest_phase_sync_sync3_reg = 1'b0;
152	
153	reg src_sync_sample_sync1_reg = 1'b0;
154	reg src_sync_sample_sync2_reg = 1'b0;
155	reg src_sync_sample_sync3_reg = 1'b0;
156	reg dest_sync_sample_sync1_reg = 1'b0;
157	reg dest_sync_sample_sync2_reg = 1'b0;
158	reg dest_sync_sample_sync3_reg = 1'b0;
159	
160	reg [SAMPLE_ACC_WIDTH-1:0] sample_acc_reg = 0;
161	reg [SAMPLE_ACC_WIDTH-1:0] sample_acc_out_reg = 0;
162	reg [LOG_SAMPLE_SYNC_RATE-1:0] sample_cnt_reg = 0;
163	reg sample_update_reg = 1'b0;
164	reg sample_update_sync1_reg = 1'b0;
165	reg sample_update_sync2_reg = 1'b0;
166	reg sample_update_sync3_reg = 1'b0;
167	
168	generate
169	
170	if (PIPELINE_OUTPUT > 0) begin
171	
172	    // pipeline
173	    (* shreg_extract = "no" *)
174	    reg [TS_WIDTH-1:0]  output_ts_reg[0:PIPELINE_OUTPUT-1];
175	    (* shreg_extract = "no" *)
176	    reg                 output_ts_step_reg[0:PIPELINE_OUTPUT-1];
177	    (* shreg_extract = "no" *)
178	    reg                 output_pps_reg[0:PIPELINE_OUTPUT-1];
179	
180	    assign output_ts = output_ts_reg[PIPELINE_OUTPUT-1];
181	    assign output_ts_step = output_ts_step_reg[PIPELINE_OUTPUT-1];
182	    assign output_pps = output_pps_reg[PIPELINE_OUTPUT-1];
183	
184	    integer i;
185	
186	    initial begin
187	        for (i = 0; i < PIPELINE_OUTPUT; i = i + 1) begin
188	            output_ts_reg[i] = 0;
189	            output_ts_step_reg[i] = 1'b0;
190	            output_pps_reg[i] = 1'b0;
191	        end
192	    end
193	
194	    always @(posedge output_clk) begin
195	        if (TS_WIDTH == 96) begin
196	            output_ts_reg[0][95:48] <= ts_s_reg;
197	            output_ts_reg[0][47:46] <= 2'b00;
198	            output_ts_reg[0][45:0]  <= {ts_ns_reg, 16'd0} >> FNS_WIDTH;
199	        end else if (TS_WIDTH == 64) begin
200	            output_ts_reg[0]  <= {ts_ns_reg, 16'd0} >> FNS_WIDTH;
201	        end
202	
203	        output_ts_step_reg[0] <= ts_step_reg;
204	        output_pps_reg[0] <= pps_reg;
205	
206	        for (i = 0; i < PIPELINE_OUTPUT-1; i = i + 1) begin
207	            output_ts_reg[i+1] <= output_ts_reg[i];
208	            output_ts_step_reg[i+1] <= output_ts_step_reg[i];
209	            output_pps_reg[i+1] <= output_pps_reg[i];
210	        end
211	
212	        if (output_rst) begin
213	            for (i = 0; i < PIPELINE_OUTPUT; i = i + 1) begin
214	                output_ts_reg[i] <= 0;
215	                output_ts_step_reg[i] <= 1'b0;
216	                output_pps_reg[i] <= 1'b0;
217	            end
218	        end
219	    end
220	
221	end else begin
222	
223	    if (TS_WIDTH == 96) begin
224	        assign output_ts[95:48] = ts_s_reg;
225	        assign output_ts[47:46] = 2'b00;
226	        assign output_ts[45:0]  = {ts_ns_reg, 16'd0} >> FNS_WIDTH;
227	    end else if (TS_WIDTH == 64) begin
228	        assign output_ts = {ts_ns_reg, 16'd0} >> FNS_WIDTH;
229	    end
230	
231	    assign output_ts_step = ts_step_reg;
232	
233	    assign output_pps = pps_reg;
234	
235	end
236	
237	endgenerate
238	
239	integer i;
240	
241	initial begin
242	    for (i = 0; i < PIPELINE_OUTPUT; i = i + 1) begin
243	        ts_s_pipe_reg[i] = 0;
244	        ts_ns_pipe_reg[i] = 0;
245	        ts_step_pipe_reg[i] = 1'b0;
246	        pps_pipe_reg[i] = 1'b0;
247	    end
248	end
249	
250	// source PTP clock capture and sync logic
251	reg input_ts_step_reg = 1'b0;
252	
253	always @(posedge input_clk) begin
254	    input_ts_step_reg <= input_ts_step || input_ts_step_reg;
255	
256	    src_phase_sync_reg <= input_ts[16+8];
257	
258	    {src_update_reg, src_phase_reg} <= src_phase_reg+1;
259	
260	    if (src_update_reg) begin
261	        // capture source TS
262	        if (TS_WIDTH == 96) begin
263	            src_ts_s_capt_reg <= input_ts[95:48];
264	            src_ts_ns_capt_reg <= input_ts[45:0] >> (16-CMP_FNS_WIDTH);
265	        end else begin
266	            src_ts_ns_capt_reg <= input_ts >> (16-CMP_FNS_WIDTH);
267	        end
268	        src_ts_step_capt_reg <= input_ts_step || input_ts_step_reg;
269	        input_ts_step_reg <= 1'b0;
270	        src_sync_reg <= !src_sync_reg;
271	    end
272	
273	    if (input_rst) begin
274	        input_ts_step_reg <= 1'b0;
275	
276	        src_phase_reg <= {PHASE_CNT_WIDTH{1'b0}};
277	        src_sync_reg <= 1'b0;
278	        src_update_reg <= 1'b0;
279	    end
280	end
281	
282	// CDC logic
283	always @(posedge output_clk) begin
284	    src_sync_sync1_reg <= src_sync_reg;
285	    src_sync_sync2_reg <= src_sync_sync1_reg;
286	    src_sync_sync3_reg <= src_sync_sync2_reg;
287	    src_phase_sync_sync1_reg <= src_phase_sync_reg;
288	    src_phase_sync_sync2_reg <= src_phase_sync_sync1_reg;
289	    src_phase_sync_sync3_reg <= src_phase_sync_sync2_reg;
290	    dest_phase_sync_sync1_reg <= dest_phase_sync_reg;
291	    dest_phase_sync_sync2_reg <= dest_phase_sync_sync1_reg;
292	    dest_phase_sync_sync3_reg <= dest_phase_sync_sync2_reg;
293	end
294	
295	always @(posedge sample_clk) begin
296	    src_sync_sample_sync1_reg <= src_sync_reg;
297	    src_sync_sample_sync2_reg <= src_sync_sample_sync1_reg;
298	    src_sync_sample_sync3_reg <= src_sync_sample_sync2_reg;
299	    dest_sync_sample_sync1_reg <= dest_sync_reg;
300	    dest_sync_sample_sync2_reg <= dest_sync_sample_sync1_reg;
301	    dest_sync_sample_sync3_reg <= dest_sync_sample_sync2_reg;
302	end
303	
304	reg edge_1_reg = 1'b0;
305	reg edge_2_reg = 1'b0;
306	
307	reg [3:0] active_reg = 0;
308	
309	always @(posedge sample_clk) begin
310	    // phase and frequency detector
311	    if (dest_sync_sample_sync2_reg && !dest_sync_sample_sync3_reg) begin
312	        if (src_sync_sample_sync2_reg && !src_sync_sample_sync3_reg) begin
313	            edge_1_reg <= 1'b0;
314	            edge_2_reg <= 1'b0;
315	        end else begin
316	            edge_1_reg <= !edge_2_reg;
317	            edge_2_reg <= 1'b0;
318	        end
319	    end else if (src_sync_sample_sync2_reg && !src_sync_sample_sync3_reg) begin
320	        edge_1_reg <= 1'b0;
321	        edge_2_reg <= !edge_1_reg;
322	    end
323	
324	    // accumulator
325	    sample_acc_reg <= $signed(sample_acc_reg) + $signed({1'b0, edge_2_reg}) - $signed({1'b0, edge_1_reg});
326	
327	    sample_cnt_reg <= sample_cnt_reg + 1;
328	
329	    if (src_sync_sample_sync2_reg && !src_sync_sample_sync3_reg) begin
330	        active_reg[0] <= 1'b1;
331	    end
332	
333	    if (sample_cnt_reg == 0) begin
334	        active_reg <= {active_reg, src_sync_sample_sync2_reg && !src_sync_sample_sync3_reg};
335	        sample_acc_reg <= $signed({1'b0, edge_2_reg}) - $signed({1'b0, edge_1_reg});
336	        sample_acc_out_reg <= sample_acc_reg;
337	        if (active_reg != 0) begin
338	            sample_update_reg <= !sample_update_reg;
339	        end
340	    end
341	end
342	
343	always @(posedge output_clk) begin
344	    sample_update_sync1_reg <= sample_update_reg;
345	    sample_update_sync2_reg <= sample_update_sync1_reg;
346	    sample_update_sync3_reg <= sample_update_sync2_reg;
347	end
348	
349	reg [SAMPLE_ACC_WIDTH-1:0] sample_acc_sync_reg = 0;
350	reg sample_acc_sync_valid_reg = 0;
351	
352	reg [PHASE_ACC_WIDTH-1:0] dest_err_int_reg = 0, dest_err_int_next = 0;
353	reg [1:0] dest_ovf;
354	
355	reg [DEST_SYNC_LOCK_WIDTH-1:0] dest_sync_lock_count_reg = 0, dest_sync_lock_count_next;
356	reg dest_sync_locked_reg = 1'b0, dest_sync_locked_next;
357	
358	always @* begin
359	    {dest_update_next, dest_phase_next} = dest_phase_reg + dest_phase_inc_reg;
360	    dest_phase_inc_next = dest_phase_inc_reg;
361	
362	    dest_err_int_next = dest_err_int_reg;
363	
364	    dest_sync_lock_count_next = dest_sync_lock_count_reg;
365	    dest_sync_locked_next = dest_sync_locked_reg;
366	
367	    if (sample_acc_sync_valid_reg) begin
368	        // updated sampled dest_phase error
369	
370	        // time integral of error
371	        if (dest_sync_locked_reg) begin
372	            {dest_ovf, dest_err_int_next} = $signed({1'b0, dest_err_int_reg}) + $signed(sample_acc_sync_reg);
373	        end else begin
374	            {dest_ovf, dest_err_int_next} = $signed({1'b0, dest_err_int_reg}) + ($signed(sample_acc_sync_reg) * 2**6);
375	        end
376	
377	        // saturate
378	        if (dest_ovf[1]) begin
379	            // sign bit set indicating underflow across zero; saturate to zero
380	            dest_err_int_next = {PHASE_ACC_WIDTH{1'b0}};
381	        end else if (dest_ovf[0]) begin
382	            // sign bit clear but carry bit set indicating overflow; saturate to all 1
383	            dest_err_int_next = {PHASE_ACC_WIDTH{1'b1}};
384	        end
385	
386	        // compute output
387	        if (dest_sync_locked_reg) begin
388	            {dest_ovf, dest_phase_inc_next} = $signed({1'b0, dest_err_int_reg}) + ($signed(sample_acc_sync_reg) * 2**4);
389	        end else begin
390	            {dest_ovf, dest_phase_inc_next} = $signed({1'b0, dest_err_int_reg}) + ($signed(sample_acc_sync_reg) * 2**10);
391	        end
392	
393	        // saturate
394	        if (dest_ovf[1]) begin
395	            // sign bit set indicating underflow across zero; saturate to zero
396	            dest_phase_inc_next = {PHASE_ACC_WIDTH{1'b0}};
397	        end else if (dest_ovf[0]) begin
398	            // sign bit clear but carry bit set indicating overflow; saturate to all 1
399	            dest_phase_inc_next = {PHASE_ACC_WIDTH{1'b1}};
400	        end
401	
402	        // locked status
403	        if ($signed(sample_acc_sync_reg[SAMPLE_ACC_WIDTH-1:2]) == 0 || $signed(sample_acc_sync_reg[SAMPLE_ACC_WIDTH-1:1]) == -1) begin
404	            if (dest_sync_lock_count_reg == {DEST_SYNC_LOCK_WIDTH{1'b1}}) begin
405	                dest_sync_locked_next = 1'b1;
406	            end else begin
407	                dest_sync_lock_count_next = dest_sync_lock_count_reg + 1;
408	            end
409	        end else begin
410	            dest_sync_lock_count_next = 0;
411	            dest_sync_locked_next = 1'b0;
412	        end
413	    end
414	end
415	
416	reg [PHASE_ERR_ACC_WIDTH-1:0] phase_err_acc_reg = 0;
417	reg [PHASE_ERR_ACC_WIDTH-1:0] phase_err_out_reg = 0;
418	reg [LOG_PHASE_ERR_RATE-1:0] phase_err_cnt_reg = 0;
419	reg phase_err_out_valid_reg = 0;
420	
421	reg phase_edge_1_reg = 1'b0;
422	reg phase_edge_2_reg = 1'b0;
423	
424	reg [5:0] phase_active_reg = 0;
425	
426	reg ts_sync_valid_reg = 1'b0;
427	reg ts_capt_valid_reg = 1'b0;
428	
429	always @(posedge output_clk) begin
430	    dest_phase_reg <= dest_phase_next;
431	    dest_phase_inc_reg <= dest_phase_inc_next;
432	    dest_update_reg <= dest_update_next;
433	
434	    sample_acc_sync_valid_reg <= 1'b0;
435	    if (sample_update_sync2_reg ^ sample_update_sync3_reg) begin
436	        // latch in synchronized counts from phase detector
437	        sample_acc_sync_reg <= sample_acc_out_reg;
438	        sample_acc_sync_valid_reg <= 1'b1;
439	    end
440	
441	    if (PIPELINE_OUTPUT > 0) begin
442	        dest_phase_sync_reg <= ts_ns_pipe_reg[PIPELINE_OUTPUT-1][8+FNS_WIDTH];
443	    end else begin
444	        dest_phase_sync_reg <= ts_ns_reg[8+FNS_WIDTH];
445	    end
446	
447	    // phase and frequency detector
448	    if (dest_phase_sync_sync2_reg && !dest_phase_sync_sync3_reg) begin
449	        if (src_phase_sync_sync2_reg && !src_phase_sync_sync3_reg) begin
450	            phase_edge_1_reg <= 1'b0;
451	            phase_edge_2_reg <= 1'b0;
452	        end else begin
453	            phase_edge_1_reg <= !phase_edge_2_reg;
454	            phase_edge_2_reg <= 1'b0;
455	        end
456	    end else if (src_phase_sync_sync2_reg && !src_phase_sync_sync3_reg) begin
457	        phase_edge_1_reg <= 1'b0;
458	        phase_edge_2_reg <= !phase_edge_1_reg;
459	    end
460	
461	    // accumulator
462	    phase_err_acc_reg <= $signed(phase_err_acc_reg) + $signed({1'b0, phase_edge_2_reg}) - $signed({1'b0, phase_edge_1_reg});
463	
464	    phase_err_cnt_reg <= phase_err_cnt_reg + 1;
465	
466	    if (src_phase_sync_sync2_reg && !src_phase_sync_sync3_reg) begin
467	        phase_active_reg[0] <= 1'b1;
468	    end
469	
470	    phase_err_out_valid_reg <= 1'b0;
471	    if (phase_err_cnt_reg == 0) begin
472	        phase_active_reg <= {phase_active_reg, src_phase_sync_sync2_reg && !src_phase_sync_sync3_reg};
473	        phase_err_acc_reg <= $signed({1'b0, phase_edge_2_reg}) - $signed({1'b0, phase_edge_1_reg});
474	        phase_err_out_reg <= phase_err_acc_reg;
475	        if (phase_active_reg != 0) begin
476	            phase_err_out_valid_reg <= 1'b1;
477	        end
478	    end
479	
480	    if (dest_update_reg) begin
481	        // capture local TS
482	        if (PIPELINE_OUTPUT > 0) begin
483	            dest_ts_s_capt_reg <= ts_s_pipe_reg[PIPELINE_OUTPUT-1];
484	            dest_ts_ns_capt_reg <= ts_ns_pipe_reg[PIPELINE_OUTPUT-1];
485	        end else begin
486	            dest_ts_s_capt_reg <= ts_s_reg;
487	            dest_ts_ns_capt_reg <= ts_ns_reg >> FNS_WIDTH-CMP_FNS_WIDTH;
488	        end
489	
490	        dest_sync_reg <= !dest_sync_reg;
491	        ts_capt_valid_reg <= 1'b1;
492	    end
493	
494	    if (src_sync_sync2_reg ^ src_sync_sync3_reg) begin
495	        // store captured source TS
496	        if (TS_WIDTH == 96) begin
497	            src_ts_s_sync_reg <= src_ts_s_capt_reg;
498	        end
499	        src_ts_ns_sync_reg <= src_ts_ns_capt_reg;
500	        src_ts_step_sync_reg <= src_ts_step_capt_reg;
501	
502	        ts_sync_valid_reg <= 1'b1;
503	    end
504	
505	    if (ts_sync_valid_reg && ts_capt_valid_reg) begin
506	        ts_sync_valid_reg <= 1'b0;
507	        ts_capt_valid_reg <= 1'b0;
508	    end
509	
510	    dest_err_int_reg <= dest_err_int_next;
511	
512	    dest_sync_lock_count_reg <= dest_sync_lock_count_next;
513	    dest_sync_locked_reg <= dest_sync_locked_next;
514	
515	    if (output_rst) begin
516	        dest_phase_reg <= {PHASE_ACC_WIDTH{1'b0}};
517	        dest_phase_inc_reg <= {PHASE_ACC_WIDTH{1'b0}};
518	        dest_sync_reg <= 1'b0;
519	        dest_update_reg <= 1'b0;
520	
521	        dest_err_int_reg <= 0;
522	
523	        dest_sync_lock_count_reg <= 0;
524	        dest_sync_locked_reg <= 1'b0;
525	
526	        ts_sync_valid_reg <= 1'b0;
527	        ts_capt_valid_reg <= 1'b0;
528	    end
529	end
530	
531	reg ts_diff_reg = 1'b0, ts_diff_next;
532	reg ts_diff_valid_reg = 1'b0, ts_diff_valid_next;
533	reg [3:0] mismatch_cnt_reg = 0, mismatch_cnt_next;
534	reg load_ts_reg = 1'b0, load_ts_next;
535	
536	reg [9+CMP_FNS_WIDTH-1:0] ts_ns_diff_reg = 0, ts_ns_diff_next;
537	
538	reg [TIME_ERR_INT_WIDTH-1:0] time_err_int_reg = 0, time_err_int_next;
539	
540	reg [1:0] ptp_ovf;
541	
542	reg [FREQ_LOCK_WIDTH-1:0] freq_lock_count_reg = 0, freq_lock_count_next;
543	reg freq_locked_reg = 1'b0, freq_locked_next;
544	reg [PTP_LOCK_WIDTH-1:0] ptp_lock_count_reg = 0, ptp_lock_count_next;
545	reg ptp_locked_reg = 1'b0, ptp_locked_next;
546	
547	reg gain_sel_reg = 0, gain_sel_next;
548	
549	assign locked = ptp_locked_reg && freq_locked_reg && dest_sync_locked_reg;
550	
551	always @* begin
552	    period_ns_next = period_ns_reg;
553	
554	    ts_s_next = ts_s_reg;
555	    ts_ns_next = ts_ns_reg;
556	    ts_ns_inc_next = ts_ns_inc_reg;
557	    ts_ns_ovf_next = ts_ns_ovf_reg;
558	
559	    ts_step_next = 0;
560	
561	    ts_diff_next = 1'b0;
562	    ts_diff_valid_next = 1'b0;
563	    mismatch_cnt_next = mismatch_cnt_reg;
564	    load_ts_next = load_ts_reg;
565	
566	    ts_ns_diff_next = ts_ns_diff_reg;
567	
568	    time_err_int_next = time_err_int_reg;
569	
570	    freq_lock_count_next = freq_lock_count_reg;
571	    freq_locked_next = freq_locked_reg;
572	    ptp_lock_count_next = ptp_lock_count_reg;
573	    ptp_locked_next = ptp_locked_reg;
574	
575	    gain_sel_next = gain_sel_reg;
576	
577	    // PTP clock
578	    period_ns_delay_next = period_ns_reg;
579	    period_ns_ovf_next = {NS_PER_S, {FNS_WIDTH{1'b0}}} - period_ns_reg;
580	
581	    if (TS_WIDTH == 96) begin
582	        // 96 bit timestamp
583	        ts_ns_inc_next = ts_ns_inc_reg + period_ns_delay_reg;
584	        ts_ns_ovf_next = ts_ns_inc_reg - period_ns_ovf_reg;
585	        ts_ns_next = ts_ns_inc_reg;
586	
587	        if (!ts_ns_ovf_reg[30+FNS_WIDTH]) begin
588	            // if the overflow lookahead did not borrow, one second has elapsed
589	            // increment seconds field, pre-compute normal increment, force overflow lookahead borrow bit set
590	            ts_ns_inc_next = ts_ns_ovf_reg + period_ns_delay_reg;
591	            ts_ns_ovf_next[30+FNS_WIDTH] = 1'b1;
592	            ts_ns_next = ts_ns_ovf_reg;
593	            ts_s_next = ts_s_reg + 1;
594	        end
595	    end else if (TS_WIDTH == 64) begin
596	        // 64 bit timestamp
597	        ts_ns_next = ts_ns_reg + period_ns_reg;
598	    end
599	
600	    if (ts_sync_valid_reg && ts_capt_valid_reg) begin
601	        // Read new value
602	        if (TS_WIDTH == 96) begin
603	            if (src_ts_step_sync_reg || load_ts_reg) begin
604	                // input stepped
605	                load_ts_next = 1'b0;
606	
607	                ts_s_next = src_ts_s_sync_reg;
608	                ts_ns_next[TS_NS_WIDTH+FNS_WIDTH-1:9+FNS_WIDTH] = src_ts_ns_sync_reg[TS_NS_WIDTH+CMP_FNS_WIDTH-1:9+CMP_FNS_WIDTH];
609	                ts_ns_inc_next[TS_NS_WIDTH+FNS_WIDTH-1:9+FNS_WIDTH] = src_ts_ns_sync_reg[TS_NS_WIDTH+CMP_FNS_WIDTH-1:9+CMP_FNS_WIDTH];
610	                ts_ns_ovf_next[30+FNS_WIDTH] = 1'b1;
611	                ts_step_next = 1;
612	            end else begin
613	                // input did not step
614	                load_ts_next = 1'b0;
615	                ts_diff_valid_next = freq_locked_reg;
616	            end
617	            // compute difference
618	            ts_ns_diff_next = src_ts_ns_sync_reg - dest_ts_ns_capt_reg;
619	            ts_diff_next = src_ts_s_sync_reg != dest_ts_s_capt_reg || src_ts_ns_sync_reg[TS_NS_WIDTH+CMP_FNS_WIDTH-1:9+CMP_FNS_WIDTH] != dest_ts_ns_capt_reg[TS_NS_WIDTH+CMP_FNS_WIDTH-1:9+CMP_FNS_WIDTH];
620	        end else if (TS_WIDTH == 64) begin
621	            if (src_ts_step_sync_reg || load_ts_reg) begin
622	                // input stepped
623	                load_ts_next = 1'b0;
624	
625	                ts_ns_next[TS_NS_WIDTH+FNS_WIDTH-1:9+FNS_WIDTH] = src_ts_ns_sync_reg[TS_NS_WIDTH+CMP_FNS_WIDTH-1:9+CMP_FNS_WIDTH];
626	                ts_step_next = 1;
627	            end else begin
628	                // input did not step
629	                load_ts_next = 1'b0;
630	                ts_diff_valid_next = freq_locked_reg;
631	            end
632	            // compute difference
633	            ts_ns_diff_next = src_ts_ns_sync_reg - dest_ts_ns_capt_reg;
634	            ts_diff_next = src_ts_ns_sync_reg[TS_NS_WIDTH+CMP_FNS_WIDTH-1:9+CMP_FNS_WIDTH] != dest_ts_ns_capt_reg[TS_NS_WIDTH+CMP_FNS_WIDTH-1:9+CMP_FNS_WIDTH];
635	        end
636	    end
637	
638	    if (ts_diff_valid_reg) begin
639	        if (ts_diff_reg) begin
640	            if (&mismatch_cnt_reg) begin
641	                load_ts_next = 1'b1;
642	                mismatch_cnt_next = 0;
643	            end else begin
644	                mismatch_cnt_next = mismatch_cnt_reg + 1;
645	            end
646	        end else begin
647	            mismatch_cnt_next = 0;
648	        end
649	    end
650	
651	    if (phase_err_out_valid_reg) begin
652	        // coarse phase/frequency lock of PTP clock
653	        if ($signed(phase_err_out_reg) > 4 || $signed(phase_err_out_reg) < -4) begin
654	            if (freq_lock_count_reg) begin
655	                freq_lock_count_next = freq_lock_count_reg - 1;
656	            end else begin
657	                freq_locked_next = 1'b0;
658	            end
659	        end else begin
660	            if (&freq_lock_count_reg) begin
661	                freq_locked_next = 1'b1;
662	            end else begin
663	                freq_lock_count_next = freq_lock_count_reg + 1;
664	            end
665	        end
666	
667	        if (!freq_locked_reg) begin
668	            ts_ns_diff_next = $signed(phase_err_out_reg) * 8 * 2**CMP_FNS_WIDTH;
669	            ts_diff_valid_next = 1'b1;
670	        end
671	    end
672	
673	    if (ts_diff_valid_reg) begin
674	        // PI control
675	
676	        // gain scheduling
677	        casez (ts_ns_diff_reg[9+CMP_FNS_WIDTH-5 +: 5])
678	            5'b01zzz: gain_sel_next = 1'b1;
679	            5'b001zz: gain_sel_next = 1'b1;
680	            5'b0001z: gain_sel_next = 1'b1;
681	            5'b00001: gain_sel_next = 1'b1;
682	            5'b00000: gain_sel_next = 1'b0;
683	            5'b11111: gain_sel_next = 1'b0;
684	            5'b11110: gain_sel_next = 1'b1;
685	            5'b1110z: gain_sel_next = 1'b1;
686	            5'b110zz: gain_sel_next = 1'b1;
687	            5'b10zzz: gain_sel_next = 1'b1;
688	            default: gain_sel_next = 1'b0;
689	        endcase
690	
691	        // time integral of error
692	        case (gain_sel_reg)
693	            1'b0: {ptp_ovf, time_err_int_next} = $signed({1'b0, time_err_int_reg}) + ($signed(ts_ns_diff_reg) / 2**4);
694	            1'b1: {ptp_ovf, time_err_int_next} = $signed({1'b0, time_err_int_reg}) + ($signed(ts_ns_diff_reg) * 2**2);
695	        endcase
696	
697	        // saturate
698	        if (ptp_ovf[1]) begin
699	            // sign bit set indicating underflow across zero; saturate to zero
700	            time_err_int_next = {TIME_ERR_INT_WIDTH{1'b0}};
701	        end else if (ptp_ovf[0]) begin
702	            // sign bit clear but carry bit set indicating overflow; saturate to all 1
703	            time_err_int_next = {TIME_ERR_INT_WIDTH{1'b1}};
704	        end
705	
706	        // compute output
707	        case (gain_sel_reg)
708	            1'b0: {ptp_ovf, period_ns_next} = $signed({1'b0, time_err_int_reg}) + ($signed(ts_ns_diff_reg) * 2**2);
709	            1'b1: {ptp_ovf, period_ns_next} = $signed({1'b0, time_err_int_reg}) + ($signed(ts_ns_diff_reg) * 2**6);
710	        endcase
711	
712	        // saturate
713	        if (ptp_ovf[1]) begin
714	            // sign bit set indicating underflow across zero; saturate to zero
715	            period_ns_next = {NS_WIDTH+FNS_WIDTH{1'b0}};
716	        end else if (ptp_ovf[0]) begin
717	            // sign bit clear but carry bit set indicating overflow; saturate to all 1
718	            period_ns_next = {NS_WIDTH+FNS_WIDTH{1'b1}};
719	        end
720	
721	        // adjust period if integrator is saturated
722	        if (time_err_int_reg == 0) begin
723	            period_ns_next = {NS_WIDTH+FNS_WIDTH{1'b0}};
724	        end else if (~time_err_int_reg == 0) begin
725	            period_ns_next = {NS_WIDTH+FNS_WIDTH{1'b1}};
726	        end
727	
728	        // locked status
729	        if (!freq_locked_reg) begin
730	            ptp_lock_count_next = 0;
731	            ptp_locked_next = 1'b0;
732	        end else if (gain_sel_reg == 1'b0) begin
733	            if (&ptp_lock_count_reg) begin
734	                ptp_locked_next = 1'b1;
735	            end else begin
736	                ptp_lock_count_next = ptp_lock_count_reg + 1;
737	            end
738	        end else begin
739	            if (ptp_lock_count_reg) begin
740	                ptp_lock_count_next = ptp_lock_count_reg - 1;
741	            end else begin
742	                ptp_locked_next = 1'b0;
743	            end
744	        end
745	    end
746	end
747	
748	always @(posedge output_clk) begin
749	    period_ns_reg <= period_ns_next;
750	    period_ns_delay_reg <= period_ns_delay_next;
751	    period_ns_ovf_reg <= period_ns_ovf_next;
752	
753	    ts_s_reg <= ts_s_next;
754	    ts_ns_reg <= ts_ns_next;
755	    ts_ns_inc_reg <= ts_ns_inc_next;
756	    ts_ns_ovf_reg <= ts_ns_ovf_next;
757	
758	    ts_step_reg <= ts_step_next;
759	
760	    ts_diff_reg <= ts_diff_next;
761	    ts_diff_valid_reg <= ts_diff_valid_next;
762	    mismatch_cnt_reg <= mismatch_cnt_next;
763	    load_ts_reg <= load_ts_next;
764	
765	    ts_ns_diff_reg <= ts_ns_diff_next;
766	
767	    time_err_int_reg <= time_err_int_next;
768	
769	    freq_lock_count_reg <= freq_lock_count_next;
770	    freq_locked_reg <= freq_locked_next;
771	    ptp_lock_count_reg <= ptp_lock_count_next;
772	    ptp_locked_reg <= ptp_locked_next;
773	
774	    gain_sel_reg <= gain_sel_next;
775	
776	    // PPS output
777	    if (TS_WIDTH == 96) begin
778	        pps_reg <= !ts_ns_ovf_reg[30+FNS_WIDTH];
779	    end else if (TS_WIDTH == 64) begin
780	        pps_reg <= 1'b0; // not currently implemented for 64 bit timestamp format
781	    end
782	
783	    // pipeline
784	    if (PIPELINE_OUTPUT > 0) begin
785	        ts_s_pipe_reg[0] <= ts_s_reg;
786	        ts_ns_pipe_reg[0] <= ts_ns_reg >> FNS_WIDTH-TS_FNS_WIDTH;
787	        ts_step_pipe_reg[0] <= ts_step_reg;
788	        pps_pipe_reg[0] <= pps_reg;
789	
790	        for (i = 0; i < PIPELINE_OUTPUT-1; i = i + 1) begin
791	            ts_s_pipe_reg[i+1] <= ts_s_pipe_reg[i];
792	            ts_ns_pipe_reg[i+1] <= ts_ns_pipe_reg[i];
793	            ts_step_pipe_reg[i+1] <= ts_step_pipe_reg[i];
794	            pps_pipe_reg[i+1] <= pps_pipe_reg[i];
795	        end
796	    end
797	
798	    if (output_rst) begin
799	        period_ns_reg <= 0;
800	        ts_s_reg <= 0;
801	        ts_ns_reg <= 0;
802	        ts_ns_inc_reg <= 0;
803	        ts_ns_ovf_reg[30+FNS_WIDTH] <= 1'b1;
804	        ts_step_reg <= 0;
805	        pps_reg <= 0;
806	
807	        ts_diff_reg <= 1'b0;
808	        ts_diff_valid_reg <= 1'b0;
809	        mismatch_cnt_reg <= 0;
810	        load_ts_reg <= 0;
811	
812	        time_err_int_reg <= 0;
813	
814	        freq_lock_count_reg <= 0;
815	        freq_locked_reg <= 1'b0;
816	        ptp_lock_count_reg <= 0;
817	        ptp_locked_reg <= 1'b0;
818	
819	        for (i = 0; i < PIPELINE_OUTPUT; i = i + 1) begin
820	            ts_s_pipe_reg[i] <= 0;
821	            ts_ns_pipe_reg[i] <= 0;
822	            ts_step_pipe_reg[i] <= 1'b0;
823	            pps_pipe_reg[i] <= 1'b0;
824	        end
825	    end
826	end
827	
828	endmodule
829	
